  'settings.general.autoCompactHint': 'When a session nears the model context limit, earlier turns are summarized automatically (history display is untouched; trigger ratio and retention ratio are set by the two sliders below)',
  'settings.general.compactTrigger': 'Compaction trigger threshold',
  'settings.general.compactTriggerHint': 'Once real context usage reaches this percentage of the model window, earlier turns are folded into a summary. Lower = compact sooner (saves tokens, drops raw text sooner); higher = keep more full context. Capped at 80%: the remaining 20% of the window is kept for the reply. Default 80%.',
  'settings.general.compactKeep': 'Recent retention ratio',
