const lang = ref<Lang>(loadLang())

function loadLang(): Lang {
  try {
    const saved = localStore.getItem(STORAGE_KEY)
    return saved === 'en' ? 'en' : 'zh'
  } catch {
    return 'zh'
  }
}

/** 0915：localStore 是异步水合的，而本模块在 import 期就会读一次语言 —— 水合完成后调用它纠正。 */
export function reloadLang(): void {
  lang.value = loadLang()
}

export function t(key: string, params?: Record<string, string | number>): string {
  const dict = lang.value === 'en' ? en : zh
  let text = dict[key] ?? key
  if (params) {
    for (const [k, v] of Object.entries(params)) {
      text = text.replace(new RegExp(`\\{${k}\\}`, 'g'), String(v))
    }
  }
  return text
}

export function setLang(l: Lang) {
  lang.value = l
  try {
    localStore.setItem(STORAGE_KEY, l)
  } catch {
    /* ignore */
  }
}

export function useI18n() {
  return { lang, t, setLang }
}
